pub fn count_islands(grid: List[Str]) -> Int {
  let h = grid.len()
  let w = grid.get_or(0, "").len()
  var cs = grid.join("").chars()
  var count = 0
  for r in range(0, h) {
    for c in range(0, w) {
      if cs.get_or(r * w + c, ".") == "#" {
        count = count + 1
        cs = cs.set(r * w + c, ".")
        var stack: List[Pair[Int, Int]] = [Pair { first: r, second: c }]
        while not stack.is_empty() {
          let cur = stack.last().unwrap_or(Pair { first: 0, second: 0 })
          stack = stack.remove_at(stack.len() - 1)
          let around = [
            Pair { first: cur.first - 1, second: cur.second },
            Pair { first: cur.first + 1, second: cur.second },
            Pair { first: cur.first, second: cur.second - 1 },
            Pair { first: cur.first, second: cur.second + 1 },
          ]
          for nb in around {
            if nb.first >= 0 and nb.first < h and nb.second >= 0 and nb.second < w {
              if cs.get_or(nb.first * w + nb.second, ".") == "#" {
                cs = cs.set(nb.first * w + nb.second, ".")
                stack = stack.push(nb)
              }
            }
          }
        }
      }
    }
  }
  return count
}
